const body = $input.first().json.body || $input.first().json;
const vendorName = String(body.vendor_name || '').trim() || 'Unknown vendor';
const feedbackType = String(body.feedback_type || 'other').trim();
const message = String(body.message || '').trim();
const submitterEmail = String(body.submitter_email || '').trim();
const sourceUrl = String(body.source_url || '').trim();
const typeLabels = {
  data_correction: 'Data correction',
  missing_info: 'Missing information',
  suggestion: 'Suggestion',
  other: 'Other',
};
const typeLabel = typeLabels[feedbackType] || feedbackType;
const DISCORD_WEBHOOK = 'https://discordapp.com/api/webhooks/1487579959714382075/W-HF3awATW1bx5XDGMC9O4Be7pBnT2MJS8TMPlrApnPa8iaqPK2eqiKTHBMn-kzknzbR';
const discordContent = [
  '**Vendor feedback received**',
  `Vendor: ${vendorName}`,
  `Type: ${typeLabel}`,
  `Message: ${message}`,
  submitterEmail ? `From: ${submitterEmail}` : 'Submitter: anonymous',
  sourceUrl ? `Page: ${sourceUrl}` : '',
].filter(Boolean).join('\n');
const emailSubject = `[CSP Feedback] ${typeLabel} — ${vendorName}`;
const emailBody = [
  `<p><strong>Vendor:</strong> ${vendorName}</p>`,
  `<p><strong>Type:</strong> ${typeLabel}</p>`,
  `<p><strong>Message:</strong></p><p>${message.replace(/\n/g, '<br>')}</p>`,
  submitterEmail ? `<p><strong>Submitter:</strong> ${submitterEmail}</p>` : '<p><strong>Submitter:</strong> anonymous</p>',
  sourceUrl ? `<p><strong>Page:</strong> <a href="${sourceUrl}">${sourceUrl}</a></p>` : '',
].filter(Boolean).join('');
return [{ json: { vendor_name: vendorName, feedback_type: feedbackType, type_label: typeLabel, message, submitter_email: submitterEmail, source_url: sourceUrl, discord_webhook: DISCORD_WEBHOOK, discord_content: discordContent, email_subject: emailSubject, email_body: emailBody } }];
